201	pub struct WorkerState<I> {
202	    scheduler: SchedulerProfile,
203	    waiting: VecDeque<RequestState<I>>,
204	    running: Vec<RequestState<I>>,
205	    in_flight: Option<StepPlan<I>>,
206	    next_step_id: u64,
207	}
208	
209	impl<I> WorkerState<I>
210	where
211	    I: Copy + Eq,
212	{
213	    pub fn new(scheduler: SchedulerProfile) -> Result<Self> {
214	        scheduler.validate()?;
215	        Ok(Self {
216	            scheduler,
217	            waiting: VecDeque::new(),
218	            running: Vec::new(),
219	            in_flight: None,
220	            next_step_id: 0,
221	        })
222	    }
223	
224	    #[must_use]
225	    pub fn scheduler(&self) -> &SchedulerProfile {
226	        &self.scheduler
227	    }
228	
229	    pub(crate) fn preflight(
230	        &self,
231	        prompt_tokens: u32,
232	        output_tokens: u64,
233	    ) -> Option<RequestRejection> {
234	        let total_tokens = u64::from(prompt_tokens).saturating_add(output_tokens);
235	        if total_tokens > u64::from(self.scheduler.max_model_len) {
236	            return Some(RequestRejection::ModelLengthExceeded {
237	                total_tokens,
238	                max_model_len: self.scheduler.max_model_len,
239	            });
240	        }
241	        if output_tokens > 0
242	            && self.scheduler.prefill == PrefillPolicy::Whole
243	            && prompt_tokens > self.scheduler.max_num_batched_tokens
244	        {
245	            return Some(RequestRejection::WholePrefillExceedsStepBudget {
246	                prompt_tokens,
247	                max_num_batched_tokens: self.scheduler.max_num_batched_tokens,
248	            });
249	        }
250	        None
251	    }
252	
253	    pub fn submit(&mut self, request: WorkerRequest<I>) -> Result<SubmissionResult> {
254	        ensure!(
255	            self.request(request.id).is_none(),
256	            "worker request id is already active"
257	        );
258	        if let Some(rejection) =
259	            self.preflight(request.prompt_tokens, u64::from(request.output_tokens))
260	        {
261	            return Ok(SubmissionResult::Rejected(rejection));
262	        }
263	        if request.output_tokens == 0 {
264	            return Ok(SubmissionResult::Finished);
265	        }
266	        self.waiting.push_back(RequestState::new(request));
267	        Ok(SubmissionResult::Queued)
268	    }
269	
270	    #[must_use]
271	    pub fn waiting_len(&self) -> usize {
272	        self.waiting.len()
273	    }
274	
275	    #[must_use]
276	    pub fn running_len(&self) -> usize {
277	        self.running.len()
278	    }
279	
280	    #[must_use]
281	    pub fn is_idle(&self) -> bool {
282	        self.waiting.is_empty() && self.running.is_empty() && self.in_flight.is_none()
283	    }
284	
285	    #[must_use]
286	    pub fn in_flight(&self) -> Option<&StepPlan<I>> {
287	        self.in_flight.as_ref()
288	    }
289	
290	    #[must_use]
291	    pub fn request(&self, id: I) -> Option<RequestSnapshot> {
292	        self.running
293	            .iter()
294	            .chain(self.waiting.iter())
295	            .find(|request| request.id == id)
296	            .map(RequestState::snapshot)
297	    }
298	
299	    pub fn cancel(&mut self, id: I) -> CancelResult {
300	        if let Some(index) = self.waiting.iter().position(|request| request.id == id) {
301	            self.waiting.remove(index);
302	            return CancelResult::Cancelled;
303	        }
304	        let Some(index) = self.running.iter().position(|request| request.id == id) else {
305	            return CancelResult::NotFound;
306	        };
307	        if self.running[index].cancel_requested {
308	            return CancelResult::AlreadyRequested;
309	        }
310	        if self.in_flight.is_some() {
311	            self.running[index].cancel_requested = true;
312	            CancelResult::Deferred
313	        } else {
314	            self.running.remove(index);
315	            CancelResult::Cancelled
316	        }
317	    }
318	
319	    pub fn plan_step(&mut self) -> Result<Option<&StepPlan<I>>> {
320	        ensure!(
321	            self.in_flight.is_none(),
322	            "cannot plan a worker step while another step is in flight"
323	        );
324	        if self.running.is_empty() && self.waiting.is_empty() {
325	            return Ok(None);
326	        }
327	
328	        let step_id = StepId(self.next_step_id);
329	        let next_step_id = self
330	            .next_step_id
331	            .checked_add(1)
332	            .context("worker step id overflow")?;
333	        let mut remaining_budget = self.scheduler.max_num_batched_tokens;
334	        let mut decode = Vec::new();
335	        let mut sum_decode_ctx_tokens = 0_u64;
336	
337	        // vLLM V1 keeps every running decode scheduled before spending the
338	        // remaining token budget on prefill work.
339	        for request in &self.running {
340	            if request.phase != RequestPhase::Decode || request.cancel_requested {
341	                continue;
342	            }
343	            ensure!(remaining_budget > 0, "running decode exceeded token budget");
344	            remaining_budget -= 1;
345	            sum_decode_ctx_tokens = sum_decode_ctx_tokens
346	                .checked_add(u64::from(request.context_tokens))
347	                .context("decode context sum overflow")?;
348	            decode.push(DecodeWork {
349	                request_id: request.id,
350	                context_tokens: request.context_tokens,
351	            });
352	        }
353	
354	        let mut prefill = Vec::new();
355	        let mut prefill_tokens_in_step = 0_u32;
356	        let mut prefill_blocked = false;
357	        for request in &self.running {
358	            if request.phase != RequestPhase::Prefill || request.cancel_requested {
359	                continue;
360	            }
361	            let tokens = scheduled_prefill_tokens(
362	                self.scheduler.prefill,
363	                request.remaining_prefill_tokens,
364	                remaining_budget,
365	            );
366	            if tokens == 0 {
367	                prefill_blocked = true;
368	                break;
369	            }
370	            remaining_budget -= tokens;
371	            prefill_tokens_in_step += tokens;
372	            prefill.push(PrefillWork {
373	                request_id: request.id,
374	                tokens,
375	            });
376	        }
377	
378	        let mut admitted = Vec::new();
379	        while !prefill_blocked
380	            && remaining_budget > 0
381	            && self.running.len() < self.scheduler.max_num_seqs as usize
382	            && !self.waiting.is_empty()
383	        {
384	            let request = self
385	                .waiting
386	                .front()
387	                .expect("admission loop checked that a waiting request exists");
388	            let (phase, prefill_tokens) = if request.remaining_prefill_tokens == 0 {
389	                (RequestPhase::Decode, 0)
390	            } else {
391	                let tokens = scheduled_prefill_tokens(
392	                    self.scheduler.prefill,
393	                    request.remaining_prefill_tokens,
394	                    remaining_budget,
395	                );
396	                if tokens == 0 {
397	                    break;
398	                }
399	                (RequestPhase::Prefill, tokens)
400	            };
401	
402	            let mut request = self
403	                .waiting
404	                .pop_front()
405	                .context("waiting request disappeared during admission")?;
406	            request.phase = phase;
407	            admitted.push(request.id);
408	            if phase == RequestPhase::Decode {
409	                remaining_budget -= 1;
410	                decode.push(DecodeWork {
411	                    request_id: request.id,
412	                    context_tokens: 0,
413	                });
414	            } else {
415	                remaining_budget -= prefill_tokens;
416	                prefill_tokens_in_step += prefill_tokens;
417	                prefill.push(PrefillWork {
418	                    request_id: request.id,
419	                    tokens: prefill_tokens,
420	                });
421	            }
422	            self.running.push(request);
423	        }
424	
425	        let decode_reqs = u32::try_from(decode.len()).context("decode request count overflow")?;
426	        let shape = StepShape {
427	            decode_reqs,
428	            sum_decode_ctx_tokens,
429	            prefill_tokens_in_step,
430	        };
431	        ensure!(
432	            shape.decode_reqs > 0 || shape.prefill_tokens_in_step > 0,
433	            "worker with queued or running requests produced an empty step"
434	        );
435	        ensure!(
436	            shape.decode_reqs <= self.scheduler.max_num_seqs,
437	            "planned decode requests exceed sequence capacity"
438	        );
439	        ensure!(
440	            shape.decode_reqs + shape.prefill_tokens_in_step
441	                <= self.scheduler.max_num_batched_tokens,
442	            "planned step exceeds token capacity"
443	        );
444	
445	        self.next_step_id = next_step_id;
446	        self.in_flight = Some(StepPlan {
447	            id: step_id,
448	            shape,
449	            admitted,
450	            prefill,
451	            decode,
452	        });
453	        Ok(self.in_flight.as_ref())
454	    }
455	
456	    pub fn complete_step(&mut self, step_id: StepId) -> Result<StepOutcome<I>> {
457	        let current_id = self
458	            .in_flight
459	            .as_ref()
460	            .map(StepPlan::id)
461	            .context("cannot complete a worker step when no step is in flight")?;
462	        ensure!(
463	            current_id == step_id,
464	            "worker step id {} does not match in-flight step {}",
465	            step_id.get(),
466	            current_id.get()
467	        );
468	        let plan = self.in_flight.take().expect("in-flight step was checked");
469	        let mut outcome = StepOutcome {
470	            prefill: Vec::with_capacity(plan.prefill.len()),
471	            generated: Vec::with_capacity(plan.prefill.len() + plan.decode.len()),
472	            finished: Vec::new(),
473	            cancelled: Vec::new(),
474	        };
475	
476	        for work in plan.prefill {
477	            let request = self
478	                .running
479	                .iter_mut()
480	                .find(|request| request.id == work.request_id)
481	                .context("planned prefill request is no longer running")?;
482	            if request.cancel_requested {
483	                continue;
484	            }
485	            ensure!(
486	                request.phase == RequestPhase::Prefill
487	                    && work.tokens > 0
488	                    && work.tokens <= request.remaining_prefill_tokens,
489	                "invalid prefill work in completed step"
490	            );
491	            request.remaining_prefill_tokens -= work.tokens;
492	            request.context_tokens = request
493	                .context_tokens
494	                .checked_add(work.tokens)
495	                .context("prefill context length overflow")?;
496	            outcome.prefill.push(PrefillProgress {
497	                request_id: request.id,
498	                processed_tokens: work.tokens,
499	                remaining_tokens: request.remaining_prefill_tokens,
500	                context_tokens: request.context_tokens,
501	            });
502	            if request.remaining_prefill_tokens == 0 {
503	                request.phase = RequestPhase::Decode;
504	                // The final prefill logits produce the first output token; a
505	                // separate decode step here would add a spurious TTFT step.
506	                request.generated_tokens = request
507	                    .generated_tokens
508	                    .checked_add(1)
509	                    .context("generated token count overflow")?;
510	                outcome.generated.push(GeneratedToken {
511	                    request_id: request.id,
512	                    token_index: request.generated_tokens,
513	                });
514	                if request.generated_tokens == request.output_tokens {
515	                    outcome.finished.push(request.id);
516	                }
517	            }
518	        }
519	
520	        for work in plan.decode {
521	            let request = self
522	                .running
523	                .iter_mut()
524	                .find(|request| request.id == work.request_id)
525	                .context("planned decode request is no longer running")?;
526	            if request.cancel_requested {
527	                continue;
528	            }
529	            ensure!(
530	                request.phase == RequestPhase::Decode
531	                    && request.context_tokens == work.context_tokens
532	                    && request.generated_tokens < request.output_tokens,
533	                "invalid decode work in completed step"
534	            );
535	            request.context_tokens = request
536	                .context_tokens
537	                .checked_add(1)
538	                .context("decode context length overflow")?;
539	            request.generated_tokens = request
540	                .generated_tokens
541	                .checked_add(1)
542	                .context("generated token count overflow")?;
543	            outcome.generated.push(GeneratedToken {
544	                request_id: request.id,
545	                token_index: request.generated_tokens,
546	            });
547	            if request.generated_tokens == request.output_tokens {
548	                outcome.finished.push(request.id);
549	            }
550	        }
551	
552	        outcome.cancelled.extend(
553	            self.running
554	                .iter()
555	                .filter(|request| request.cancel_requested)
556	                .map(|request| request.id),
557	        );
558	        self.running
559	            .retain(|request| !request.cancel_requested && !outcome.finished.contains(&request.id));
560	        Ok(outcome)
561	    }
562	}
563	
564	fn scheduled_prefill_tokens(
565	    policy: PrefillPolicy,
566	    remaining_tokens: u32,
567	    remaining_budget: u32,
568	) -> u32 {
569	    match policy {
570	        PrefillPolicy::Whole => {
571	            if remaining_tokens <= remaining_budget {
572	                remaining_tokens
573	            } else {
574	                0
575	            }
576	        }
577	        PrefillPolicy::Chunked { max_chunk_tokens } => {
578	            remaining_tokens.min(max_chunk_tokens).min(remaining_budget)
579	        }
580	    }
581	}
