639	    #[test]
640	    fn context_and_generated_progress_end_in_one_terminal_outcome() {
641	        let mut worker = WorkerState::new(scheduler(1, 4, 16, PrefillPolicy::Whole)).unwrap();
642	        worker.submit(request(1, 3, 3)).unwrap();
643	
644	        let prefill_id = worker.plan_step().unwrap().unwrap().id();
645	        let prefill = worker.complete_step(prefill_id).unwrap();
646	        assert_eq!(
647	            prefill.generated,
648	            [GeneratedToken {
649	                request_id: 1,
650	                token_index: 1
651	            }]
652	        );
653	        assert_eq!(worker.request(1).unwrap().context_tokens, 3);
654	
655	        let decode_one = worker.plan_step().unwrap().unwrap();
656	        assert_eq!(decode_one.shape().sum_decode_ctx_tokens, 3);
657	        let decode_one_id = decode_one.id();
658	        let outcome = worker.complete_step(decode_one_id).unwrap();
659	        assert_eq!(outcome.generated[0].token_index, 2);
660	        assert_eq!(worker.request(1).unwrap().context_tokens, 4);
661	
662	        let decode_two = worker.plan_step().unwrap().unwrap();
663	        assert_eq!(decode_two.shape().sum_decode_ctx_tokens, 4);
664	        let decode_two_id = decode_two.id();
665	        let terminal = worker.complete_step(decode_two_id).unwrap();
666	        assert_eq!(terminal.finished, [1]);
667	        assert!(worker.request(1).is_none());
668	        assert!(worker.plan_step().unwrap().is_none());
669	    }
