752	        #[derive(Debug)]
753	        struct ReplayStep {
754	            id: u64,
755	            shape: StepShape,
756	            admitted: Vec<u32>,
757	            prefill: Vec<(u32, u32)>,
758	            running: usize,
759	            waiting: usize,
760	            finished: Vec<u32>,
761	            generated: Vec<(u32, u32)>,
762	        }
763	
764	        struct Replay {
765	            steps: Vec<ReplayStep>,
766	            finished: Vec<u32>,
767	            generated: Vec<(u32, u32)>,
768	        }
769	
770	        fn record_step(worker: &mut WorkerState<u32>) -> Option<ReplayStep> {
771	            let (step_id, mut step) = {
772	                let plan = worker.plan_step().unwrap()?;
773	                (
774	                    plan.id(),
775	                    ReplayStep {
776	                        id: plan.id().get(),
777	                        shape: plan.shape(),
778	                        admitted: plan.admitted().to_vec(),
779	                        prefill: plan
780	                            .prefill()
781	                            .iter()
782	                            .map(|work| (work.request_id, work.tokens))
783	                            .collect(),
784	                        running: worker.running_len(),
785	                        waiting: worker.waiting_len(),
786	                        finished: Vec::new(),
787	                        generated: Vec::new(),
788	                    },
789	                )
790	            };
791	            let outcome = worker.complete_step(step_id).unwrap();
792	            step.finished = outcome.finished;
793	            step.generated = outcome
794	                .generated
795	                .into_iter()
796	                .map(|token| (token.request_id, token.token_index))
797	                .collect();
